select f.finance_id, f.price_list, f.calc_name, f.calc_user_id, f.document_category, f.document_id, f.finance_desc, (select h.description from hls_price_list h where h.price_list = f.price_list)price_list_n, (select su.description from sys_user su where su.user_id = f.calc_user_id)calc_user_id_n, pq.quotation_id from finance_calc_price f left join prj_quotation pq on pq.source_document_category = 'FINANCE_CALC' and pq.source_document_id = f.finance_id
f.calc_user_id = #{request.userId}
and f.calc_user_id = #{calcUserId}
and f.calc_name like concat(concat('%',#{calcName}),'%')
and f.price_list = #{priceList}
order by 1 desc

select v.* from (select w.*,(case when w.cf_count > 0 then '是' else '否' end) calc_flag from (select nvl(f.price_list,pq.price_list), f.calc_name, f.calc_user_id, (select h.description from hls_price_list h where h.price_list = nvl(f.price_list,pq.price_list)) price_list_n, (select su.description from sys_user su where su.user_id = f.calc_user_id) calc_user_id_n, pq.quotation_id, pq.source_document_category, '测算报价' as document_category_n, pq.source_document_id, f.calc_name as document_id_n, (select count(1) from prj_quotation_cashflow ccc where ccc.quotation_id = pq.quotation_id) cf_count from finance_calc_price f, prj_quotation pq where pq.source_document_category = 'FINANCE_CALC' and pq.source_document_id = f.finance_id --order by pq.creation_date desc UNION ALL
select pq.price_list, pq.calc_name, pq.created_by calc_user_id, (select h.description from hls_price_list h where h.price_list = pq.price_list) price_list_n, (select su.description from sys_user su where su.user_id = pq.created_by) calc_user_id_n, pq.quotation_id, pq.source_document_category, '项目报价' as document_category_n, pq.source_document_id, p.project_name as document_id_n, (select count(1) from prj_quotation_cashflow ccc where ccc.quotation_id = pq.quotation_id) cf_count from prj_quotation pq,prj_project p where pq.source_document_id = p.project_id and p.data_class = 'NORMAL' and p.project_status = 'APPROVED' and pq.source_document_category = 'PRJ_PROJECT'
) w order by w.document_category_n, w.quotation_id desc) v
1=1
and v.calc_user_id = #{calcUserId}
and v.calc_name like concat(concat('%',#{calcName}),'%')
and v.price_list = #{priceList}
and v.calc_user_id = #{createId}
and v.document_category_n like concat(concat('%',#{documentCategoryN}),'%')
and v.document_id_n like concat(concat('%',#{documentIdN}),'%')
